bounded_host_request.command:
set -eu
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
const flags={};
try{
 const r=await pool.query(`SELECT r.delivery_key,r.status,r.topic_id,r.paid_message_id,r.free_message_ids,r.sale_mode,l.paid_video_file_id,l.title,l.price_stars,l.seller_user_id,EXTRACT(EPOCH FROM (NOW()-r.updated_at)) AS age_seconds FROM videobot_post_receipts r JOIN videobot_listings l USING(listing_id) WHERE r.status='sent' ORDER BY r.updated_at ASC`);
 const p=await pool.query("SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL");
 const keys=new Set(p.rows.map(x=>x.delivery_key));
 const protectedRows=r.rows.filter(x=>keys.has(x.delivery_key));
 if(protectedRows.length!==1)process.exitCode=41;
 else {
 const survivor=protectedRows[0];
 const duplicates=r.rows.filter(x=>x.delivery_key!==survivor.delivery_key&&x.topic_id===survivor.topic_id&&x.seller_user_id===survivor.seller_user_id&&x.title===survivor.title&&x.price_stars===survivor.price_stars&&x.paid_video_file_id===survivor.paid_video_file_id&&!keys.has(x.delivery_key));
 if(duplicates.length===0)process.exitCode=42;
 else if(duplicates.some(x=>Number(x.age_seconds)>46*3600))process.exitCode=43;
 else if(duplicates.some(x=>!Array.isArray(x.free_message_ids)||x.free_message_ids.length!==2||!Number.isSafeInteger(Number(x.paid_message_id))))process.exitCode=44;
 else process.exitCode=45;
 }
}catch{process.exitCode=46}finally{await pool.end()}
NODE
